router.post('/radiology/orders/:id/report',requirePermission('radiology.manage'),allowRoles('hospital_admin','branch_admin','doctor'),audit('radiology.report.saved','radiology_report'),asyncHandler(async(req,res)=>{const o=await RadiologyOrder.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!o)return fail(res,'Radiology order not found',404);if(!await doctorOwns(req,o.patientId))return fail(res,'Patient is not assigned to your clinical care',403);if(!clean(req.body.findings,20)||!clean(req.body.impression,10))return fail(res,'Findings and impression are required');let r=await RadiologyReport.findOne({tenantId:req.tenantId,orderId:o._id});if(r&&!['draft'].includes(r.status))return fail(res,'Submitted or finalized report cannot be overwritten',409);if(!r)r=new RadiologyReport({tenantId:req.tenantId,branchId:o.branchId,orderId:o._id,patientId:o.patientId});r.findings=clean(req.body.findings,10000);r.impression=clean(req.body.impression,5000);r.enteredBy=req.user._id;r.status='draft';await r.save();res.status(201).json({success:true,data:r});}));
router.post('/radiology/reports/:id/submit',requirePermission('radiology.manage'),allowRoles('hospital_admin','branch_admin','doctor'),asyncHandler(async(req,res)=>{const r=await RadiologyReport.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!r||r.status!=='draft')return fail(res,'Draft report not found',409);if(!await doctorOwns(req,r.patientId))return fail(res,'Patient is not assigned to your clinical care',403);r.status='pending_verification';await r.save();const o=await RadiologyOrder.findById(r.orderId);o.status='pending_verification';await o.save();res.json({success:true,data:r});}));
router.patch('/radiology/reports/:id/verify',requirePermission('radiology.manage'),allowRoles('hospital_admin','branch_admin','doctor'),audit('radiology.report.verified','radiology_report'),asyncHandler(async(req,res)=>{const r=await RadiologyReport.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!r||r.status!=='pending_verification')return fail(res,'Report is not awaiting verification',409);if(!await doctorOwns(req,r.patientId))return fail(res,'Patient is not assigned to your clinical care',403);if(String(r.enteredBy)===String(req.user._id))return fail(res,'Self-verification is prohibited',403);r.status='verified';r.verifiedBy=req.user._id;r.verifiedAt=new Date();r.finalSnapshot={findings:r.findings,impression:r.impression};await r.save();const o=await RadiologyOrder.findById(r.orderId);o.status='verified';await o.save();res.json({success:true,data:r});}));
router.patch('/radiology/reports/:id/release',requirePermission('radiology.manage'),allowRoles('hospital_admin','branch_admin','doctor'),audit('radiology.report.released','radiology_report'),asyncHandler(async(req,res)=>{const r=await RadiologyReport.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!r||r.status!=='verified')return fail(res,'Only verified reports can be released',409);if(!await doctorOwns(req,r.patientId))return fail(res,'Patient is not assigned to your clinical care',403);r.status='released';r.releasedBy=req.user._id;r.releasedAt=new Date();await r.save();await RadiologyOrder.updateOne({_id:r.orderId,tenantId:req.tenantId},{$set:{status:'released',releasedAt:r.releasedAt,releasedBy:req.user._id}});res.json({success:true,data:r});}));
router.get('/radiology/reports/:id/pdf',requirePermission('radiology.view'),asyncHandler(async(req,res)=>{const r=await RadiologyReport.findOne({_id:req.params.id,tenantId:req.tenantId,status:'released',...branchScope(req)}).populate('patientId','firstName lastName uhid dob sex').populate('orderId','orderNo modality serviceName').populate('verifiedBy','name');if(!r)return fail(res,'Released report not found',404);if(!await doctorOwns(req,r.patientId))return fail(res,'Patient is not assigned to your clinical care',403);const [branch,tenant]=await Promise.all([Branch.findOne({_id:r.branchId,tenantId:req.tenantId}).lean(),Tenant.findById(req.tenantId).lean()]);res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${r.orderId?.orderNo||'radiology-report'}.pdf"`);const doc=new PDFDocument({size:'A4',margin:48,info:{Title:'Radiology Report',Author:'CareFlow'}});doc.pipe(res);doc.fillColor('#173F35').fontSize(20).text(tenant?.name||'Healthcare Provider');doc.fontSize(10).fillColor('#333').text([branch?.name,branch?.address,branch?.city,branch?.phone].filter(Boolean).join(' · '));doc.moveDown().fontSize(17).text('RADIOLOGY REPORT');doc.fontSize(10).text(`Patient: ${r.patientId?.firstName||''} ${r.patientId?.lastName||''} (${r.patientId?.uhid||''})`);doc.text(`Order: ${r.orderId?.orderNo||''}    Modality: ${r.orderId?.modality||''}`);doc.text(`Report date: ${new Date(r.releasedAt).toLocaleString('en-IN')}`);doc.moveDown().fontSize(12).fillColor('#173F35').text('Clinical Findings');doc.fontSize(10).fillColor('#333').text(r.findings||'—');doc.moveDown().fontSize(12).fillColor('#173F35').text('Impression');doc.fontSize(10).fillColor('#333').text(r.impression||'—');doc.moveDown(2).text(`Verified by: ${r.verifiedBy?.name||'Authorized verifier'}`);doc.fontSize(8).text('This report is released from CareFlow. No cryptographic digital signature is implied.');doc.end();}));

