router.post('/source-charges/lab-orders/:id',requirePermission('billing.create'),audit('billing.lab_order.charged','invoice'),asyncHandler(async(req,res)=>{const o=await LabOrder.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!o)return fail(res,'Lab order not found',404);const tests=await LabTest.find({tenantId:req.tenantId,_id:{$in:o.items.map(i=>i.testId).filter(Boolean)}});let lines;if(o.results?.packagePrice!==undefined){const gross=Number(o.results.packagePrice||0),discount=Math.min(gross,Number(o.results.discount||0));lines=[{description:o.results.packageName||`Laboratory package ${o.orderNo}`,category:'Packages',amount:gross,discount,taxConfigurationId:o.results.packageTaxConfigurationId}];}else lines=o.items.map(item=>{const t=tests.find(x=>String(x._id)===String(item.testId));return {description:item.testName||t?.name||'Laboratory test',category:item.category||t?.category||'Uncategorised',amount:Number(item.price??t?.standardPrice??0),taxConfigurationId:item.taxConfigurationId||t?.taxConfigurationId};});const invoice=await billSource(req,{sourceType:'lab_order',sourceId:o._id,patientId:o.patientId,branchId:o.branchId,lines,description:`Laboratory order ${o.orderNo}`});res.status(201).json({success:true,data:invoice});}));
router.post('/source-charges/radiology-orders/:id',requirePermission('billing.create'),audit('billing.radiology_order.charged','invoice'),asyncHandler(async(req,res)=>{const o=await RadiologyOrder.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!o)return fail(res,'Radiology order not found',404);const service=await RadiologyService.findOne({_id:o.serviceId,tenantId:req.tenantId});if(!service)return fail(res,'Radiology service not found',404);const invoice=await billSource(req,{sourceType:'radiology_order',sourceId:o._id,patientId:o.patientId,branchId:o.branchId,lines:[{description:o.serviceName||service.name,category:o.modality||service.category,amount:o.price??service.standardPrice,taxConfigurationId:o.taxConfigurationId||service.taxConfigurationId}]});o.invoiceId=invoice._id;await o.save();res.status(201).json({success:true,data:invoice});}));

router.get('/patient-portal/diagnostic-reports/lab/:id/pdf',asyncHandler(async(req,res)=>{if(req.user.role!=='patient'||!req.user.patientId)return fail(res,'Patient portal access required',403);const r=await LabResult.findOne({_id:req.params.id,tenantId:req.tenantId,patientId:req.user.patientId,status:'released'}).populate('patientId','firstName lastName uhid').populate('orderId','orderNo');if(!r)return fail(res,'Released report not found',404);res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${r.orderId?.orderNo||'lab-report'}.pdf"`);const doc=new PDFDocument({size:'A4',margin:48});doc.pipe(res);doc.fontSize(18).text('LABORATORY REPORT');doc.fontSize(10).text(`Patient: ${r.patientId.firstName} ${r.patientId.lastName} · ${r.patientId.uhid}`);doc.text(`Order: ${r.orderId?.orderNo||''} · ${r.testName||''}`);doc.moveDown();for(const p of r.parameters||[])doc.text(`${p.name}: ${p.value} ${p.unit||''} · ${p.flag} · Reference: ${p.referenceRange||'—'}`);doc.moveDown().text(`Observations: ${r.observations||'—'}`);doc.end();}));
