router.patch('/radiology/orders/:id/cancel',requirePermission('laboratory.manage'),allowRoles('hospital_admin','branch_admin','doctor'),audit('radiology.order.cancelled','radiology_order'),asyncHandler(async(req,res)=>{const o=await RadiologyOrder.findOne({_id:req.params.id,tenantId:req.tenantId,...branchScope(req)});if(!o||['released','cancelled'].includes(o.status))return fail(res,'Order cannot be cancelled in its current state',409);if(!await doctorOwns(req,o.patientId))return fail(res,'Patient is not assigned to your clinical care',403);const reason=clean(req.body.reason,1000);if(reason.length<5)return fail(res,'Cancellation reason is required');o.status='cancelled';await o.save();if(o.scheduleId){const s=await RadiologySchedule.findOne({_id:o.scheduleId,tenantId:req.tenantId});if(s){s.status='cancelled';s.history.push({event:'cancelled',userId:req.user._id,at:new Date(),remarks:reason});await s.save();await RadiologySlotLock.deleteMany({tenantId:req.tenantId,scheduleId:s._id});}}res.json({success:true,data:o});}));
