router.get('/patient-portal/diagnostic-reports',asyncHandler(async(req,res)=>{if(req.user.role!=='patient'||!req.user.patientId)return fail(res,'Patient portal access required',403);const patient=await Patient.findOne({_id:req.user.patientId,tenantId:req.tenantId,active:true});if(!patient)return fail(res,'Patient record unavailable',404);const [lab,radiology]=await Promise.all([LabResult.find({tenantId:req.tenantId,patientId:patient._id,status:'released'}).populate('orderId','orderNo').sort({releasedAt:-1}).lean(),RadiologyReport.find({tenantId:req.tenantId,patientId:patient._id,status:'released'}).populate('orderId','orderNo modality serviceName').sort({releasedAt:-1}).lean()]);res.json({success:true,data:{laboratory:lab,radiology}});}));
